import{_ as i,C as o,o as s,c as p,E as e,a5 as l}from"./chunks/framework.DOB-AMqW.js";const b=JSON.parse('{"title":"Flowra Support","description":"Help and support information for the Flowra application.","frontmatter":{"title":"Flowra Support","description":"Help and support information for the Flowra application."},"headers":[],"relativePath":"apps/flowra/support.md","filePath":"apps/flowra/support.md"}'),c={name:"apps/flowra/support.md"};function d(u,a,m,h,f,g){const r=o("AppBreadcrumbs"),t=o("AppSubnav"),n=o("CopyStandaloneUrl");return s(),p("div",null,[e(r,{"app-id":"flowra",current:"Support"}),e(t,{"app-id":"flowra"}),e(n,{path:"/support/flowra",label:"Copy standalone support URL","copied-label":"Support URL copied","document-name":"Flowra support page"}),a[0]||(a[0]=l('<h1 id="flowra-support" tabindex="-1">Flowra Support <a class="header-anchor" href="#flowra-support" aria-label="Permalink to &quot;Flowra Support&quot;">​</a></h1><p>For Flowra support, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p><p>Include the Flowra version, Android or browser version, device model, a description of the issue, and safe reproduction steps when possible.</p><p>Do not email menstrual records, health details, PINs, passwords, screenshots containing sensitive information, or an unreviewed <code>.flowra</code> backup file.</p><h2 id="common-help" tabindex="-1">Common help <a class="header-anchor" href="#common-help" aria-label="Permalink to &quot;Common help&quot;">​</a></h2><ul><li><strong>Data is missing after reinstalling or clearing storage:</strong> Flowra has no cloud sync. Restore a password-protected backup that you created beforehand.</li><li><strong>A backup will not open:</strong> select a <code>.flowra</code> backup created by Flowra and use its exact password. Flowra cannot recover forgotten backup passwords.</li><li><strong>Reminders do not appear:</strong> enable reminders in Flowra, grant Android notification permission, confirm that a prediction exists, and check battery and notification settings for the app.</li><li><strong>Biometric unlock is unavailable:</strong> enroll a supported strong biometric in Android, unlock Flowra with the app PIN, and enable biometrics again. A change to enrolled biometrics can invalidate the saved Keystore key.</li><li><strong>The app remains locked:</strong> use the configured app PIN. Biometric unlock is an optional convenience and does not replace the PIN.</li><li><strong>Browser records disappeared:</strong> browser site-data clearing, private browsing, storage eviction, or changing browser/profile/origin can remove or isolate IndexedDB data. Restore a backup if available.</li><li><strong>CSV or PDF is not where expected:</strong> check the browser&#39;s Downloads location or the destination selected by the print/save dialog.</li></ul><p>Flowra provides estimates rather than medical advice. For health concerns, contact a qualified healthcare professional rather than sending medical details to app support.</p>',7))])}const _=i(c,[["render",d]]);export{b as __pageData,_ as default};
